            if (list.Count == 0)
            {
                PlayerInfo.SkillTime[DataId.careercard_9] -=2;
                UpdateSkillTime();
                return;
            }

            var selected = list[0] as DataConfig;
            if (selected == null)
            {
                PlayerInfo.SkillTime[DataId.careercard_9] -=2;
                UpdateSkillTime();
                return;
            }
            int expend = int.Parse(selected.data.GetValueOrDefault("Expend", "0"));
            int rarity = int.Parse(selected.data.GetValueOrDefault("Rarity", "1"));
            PlayerInfo.RemoveCard(selected.InstanceID);
            BurnCardByData(selected);
            string TargetId="";
            if (rarity <= 2)
            {
                if (expend <= 1)
                {
                    TargetId=DataId.blessing_43;
                }
                else if (expend == 2)
                {
                    TargetId=DataId.blessing_44;
                }
                else
                {
                    TargetId=DataId.blessing_45;
                }
            }
            else
            {
                if (expend <= 1)
                {
                    TargetId=DataId.blessing_46;
                }
                else if (expend == 2)
                {
                    TargetId=DataId.blessing_47;
                }
                else
                {
                    TargetId=DataId.blessing_48;
                }
            }
            PlayerInfo.AddBless(TargetId);
            DataConfig newData=new DataConfig(TargetId,DataType.Bless);
            PlayerInfo.ShowItemShowUI(newData.data["Icon"],newData.data.Localize("Name"),newData.data.Localize("Description"));
