void RandomEffect()
        {
            int count=DefaultDice.WithRange(0,96).Roll().Value/16;
            count=Math.Min(count,5);
            Vars["ThisCount"]=(count+1).ToString();
            if (Self==null||Self.GetBuff(DataId.buff_ChaosMark)==null)
            {
                return;
            }
            Self.GetBuff(DataId.buff_ChaosMark).buffConfig.Level=(count+1);
            if (count==0)
            {
                SetStatus("Self");
                if (Self.CurHp<=Self.MaxHp/5)
                {
                    ChangeHp((-1*(Self.CurHp-1)).ToString());
                }
                else
                {
                    ChangeHp((-1*(Self.MaxHp/5)).ToString());
                }
                SetStatus("AllTarget");
                var tempList=new List<IStatusManager>(Object);
                foreach (var status in tempList)
                {
                    SetStatusById(status.InstanceId);
                    ChangeHp((status.MaxHp/-10).ToString());
                }
            }
            else if(count==1)
            {
                SetStatus("Self");
                ChangeHp((Self.MaxHp*3/10).ToString());
            }
            else if(count==2)
            {
                SetStatus("Self");
                ChangePower("-1");
                DrawCount("2");
            }
            else if(count==3)
            {
                int scCount=DefaultDice.WithRange(0,100).Roll().Value;
                int thCount=DefaultDice.WithRange(0,98).Roll().Value;
                if (scCount<50)
                {
                    SetStatus("Self");
                    AddBuff(DataId.buff_burn, (thCount/33+1).ToString());
                    SetStatus("AllTarget");
                    AddBuff(DataId.buff_burn, (thCount*2/33+2).ToString());
                }
                else
                {

                    SetStatus("Self");
                    AddBuff(DataId.buff_bleeding, (thCount/33+1).ToString());
                    SetStatus("AllTarget");
                    AddBuff(DataId.buff_bleeding, (thCount*2/33+2).ToString());
                }
            }
            else if(count==4)
            {
                var buffs=Self.GetBuffs();
                foreach (var item in buffs)
                {
                    item.buffConfig.Level=item.buffConfig.Level*6/5;
                }
            }
            else 
            {
                SetStatus("Self");
                AddBuff(DataId.buff_extraordinary, "100");
            }
        }
        AddEvent("StartRound",RandomEffect);
        AddEvent("RandomEffect", RandomEffect);

