        string GetFlagByCardId(string cardId)
        {
            if (string.IsNullOrEmpty(cardId)) { return ""; }
            if (cardId == DataId.SpellCard_1 || cardId == "1" || cardId.EndsWith("_1")) { return "A"; }
            if (cardId == DataId.SpellCard_2 || cardId == "2" || cardId.EndsWith("_2")) { return "B"; }
            if (cardId == DataId.SpellCard_3 || cardId == "3" || cardId.EndsWith("_3")) { return "C"; }
