SetStatus("Self");
        Vars["CanChange"]="True";
        Vars["CurrentFate"] = "";
        void ClearFateMarks()
        {
            SetStatus("Self");
            RemoveBuff("SpecialBuff_HJE_FateJudgment");
            RemoveBuff("SpecialBuff_HJE_FateDawn");
            RemoveBuff("SpecialBuff_HJE_FateHolyMachine");
        }
        void FateShiftImpact()
        {
            SetStatus("AllExSelf");
            Damage(atk());
            for (int i = 0; i < 2; i++)
            {
                int count=DefaultDice.WithRange(1, 13).Roll().Value;
                if (count==7)
                {
                    count=11;
                }
                RandomAddCard("cursecard_" + DefaultDice.WithRange(1, 13).Roll().Value);
            }
        }
        void ApplyFate()
        {
            if (Vars["CanChange"]!="True")
            {
                return;
            }
            string nextFate;
            var fatePool = new List<string>() { "Judgment", "Dawn", "HolyMachine" };
            fatePool=fatePool.Where(x=>x!=Vars["CurrentFate"]).ToList();
            nextFate = fatePool[DefaultDice.WithRange(0, fatePool.Count - 1).Roll().Value];
            if ( Vars["CurrentFate"] == nextFate)
            {
                return;
            }
            Vars["CanChange"]="False";
            SetStatus("Self");
            ClearFateMarks();

            AddEnemyAction(new DataConfig("enemycard_HJE_"+nextFate, DataType.EnemyCard));
            if (nextFate == "Judgment")
            {
                AddBuff("SpecialBuff_HJE_FateJudgment", "1");
            }
            else if (nextFate == "Dawn")
            {
                AddBuff("SpecialBuff_HJE_FateDawn", "1");
            }
            else if (nextFate == "HolyMachine")
            {
                AddBuff("SpecialBuff_HJE_FateHolyMachine", "1");
            }
            FateShiftImpact();
            Vars["CurrentFate"] = nextFate;
        }
        void HalfNegativeBuffs()
        {
            var buffs = Self.GetBuffs();
            foreach (var item in buffs)
            {
                if (item == null || item.buffConfig == null)
                {
                    continue;
                }
                if (item.buffConfig.Type != "负面")
                {
                    continue;
                }
                item.buffConfig.Level = item.buffConfig.Level / 2;
            }
        }
        AddBuff("SpecialBuff_HJE_AbsoluteShield", "3");
        AddEvent("Resurrection", () =>
        {
            SetStatus("Self");
            HalfNegativeBuffs();
            ApplyFate();
        });
        SetStatus("AllTarget");
        AddEvent("EndRound",()=>{Vars["CanChange"]="True";});
        AddEvent("StartRound", () =>
        {
            ApplyFate();
        });

