void PlayHjeFateVisual(float pointerAngle, IStatusManager.AnimatedState eyeState)
{
    var pointer = Self?.FindSummon("指针");
    var cross = Self?.FindSummon("十字");
    var eye = Self?.FindSummon("眼睛");
    if (pointer != null)
    {
        float currentAngle = pointer.transform.localEulerAngles.z;
        if (currentAngle > 180f)
        {
            currentAngle -= 360f;
        }
        float delta = Mathf.DeltaAngle(currentAngle, pointerAngle);
        DG.Tweening.ShortcutExtensions.DOKill(pointer.transform);
        if (cross != null)
        {
            DG.Tweening.ShortcutExtensions.DOKill(cross.transform);
        }
        var sequence = DG.Tweening.DOTween.Sequence();
        float[] frameFactors = new float[] { -0.03f, -0.02f, 0.02f, 0.14f, 0.39f, 0.73f, 0.95f, 1.03f, 1.02f, 1f };
        foreach (float factor in frameFactors)
        {
            float frameAngle = currentAngle + delta * factor;
            DG.Tweening.TweenSettingsExtensions.Append(sequence,
                DG.Tweening.TweenSettingsExtensions.SetEase(
                    DG.Tweening.ShortcutExtensions.DORotate(pointer.transform, new Vector3(0, 0, frameAngle), 0.1f),
                    DG.Tweening.Ease.Linear));
            if (cross != null)
            {
                DG.Tweening.TweenSettingsExtensions.Join(sequence,
                    DG.Tweening.TweenSettingsExtensions.SetEase(
                        DG.Tweening.ShortcutExtensions.DORotate(cross.transform, new Vector3(0, 0, -frameAngle), 0.1f),
                        DG.Tweening.Ease.Linear));
            }
        }
    }
    if (eye != null)
    {
        eye.AnimationData = (eyeState, 0);
        eye.animationTimeCounter = 0f;
    }
}
