AddEvent<HurtData>("Hurt", (data) =>
{
    int hurt = data.val.ToInt();
    if (hurt <= 0 || Self == null || Self.IsNull() || Self.MaxHp <= 0)
    {
        return;
    }

    int before = Vars["LostHpCount"].ToInt();
    int after = before + hurt;

    int beforeStep = (int)(before * 10f / Self.MaxHp);
    int afterStep = (int)(after * 10f / Self.MaxHp);
    int triggerCount = afterStep - beforeStep;

    Vars["LostHpCount"] = after.ToString();

    for (int i = 0; i < triggerCount; i++)
    {
        SetStatus("Self");
        AddBuff(DataId.buff_extraordinary, "30");
        AddBuff(DataId.buff_impregnable, "3");
    }
});

